#!/usr/bin/env python3
"""Generate the tb_cartport benches (issue #259) from the real RTL text.

usage: gen_tb.py <main.vhd> <fpga64_sid_iec.vhd> <outdir>

The benches contain the verbatim process code of the unit under test, spliced
in at generation time, so that an edit of main.vhd or fpga64_sid_iec.vhd is
tested as written. Anchors are the process labels and comment lines of those
files; if an anchor disappears, this script fails loudly."""
import sys
main_p, sid_p, out = sys.argv[1], sys.argv[2], sys.argv[3]
main = open(main_p).read(); sid = open(sid_p).read()

def between(src, a, b, who):
    try:
        i = src.index(a); j = src.index(b, i) + len(b)
    except ValueError:
        sys.exit(f"anchor not found in {who}: {a[:50]!r} .. {b[:50]!r}")
    return src[i:j]

def process_around(src, needle, who):
    """the process(clk32) ... end process; block that contains needle"""
    k = src.index(needle) if needle in src else sys.exit(f"anchor not found in {who}: {needle!r}")
    i = src.rfind("process(clk32)", 0, k)
    j = src.index("end process;", k) + len("end process;")
    return src[i:j]

enum   = between(sid, "type sysCycleDef is (", ");", "fpga64_sid_iec.vhd")
pixel  = process_around(sid, "enablePixel <= '1';", "fpga64_sid_iec.vhd")
phi2p  = process_around(sid, "when CYCLE_CPU0 =>", "fpga64_sid_iec.vhd")
grant  = between(sid, "if baLoc = '1' or (cpuWe = '1' and dma_active = '0')", "then", "fpga64_sid_iec.vhd")
shaper = between(main, "  cart_dotclk_shape_proc : process (clk_main_i)", "  end process cart_dotclk_shape_proc;", "main.vhd")
baproc = between(main, "  cart_dma_ba_proc : process (clk_main_i)", "  end process cart_dma_ba_proc;", "main.vhd")
branch = between(main, "        if core_ba = '0' and core_dma_grace = '1' then",
                 "          cart_data_oe_o <= '0'; -- Leave data bus floating\n        end if;\n", "main.vhd")

TB_DOTCLK = 'library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;\nentity tb_dotclk is end;\narchitecture sim of tb_dotclk is\n  -- verbatim from fpga64_sid_iec.vhd\n{ENUM}\n  signal clk, clk32, clk_main_i : std_logic := \'0\';\n  signal sysCycle : sysCycleDef := sysCycleDef\'low;\n  signal enablePixel, phi2 : std_logic := \'0\';\n  signal core_dotclk, core_dotclk_d1, core_dotclk_d2, core_dotclk_d3, cart_dotclk_q : std_logic := \'0\';\n  signal done : boolean := false;\nbegin\n  clk <= not clk after 15.86 ns when not done;\n  clk32 <= clk; clk_main_i <= clk; core_dotclk <= enablePixel;\n  \n  process(clk) begin if rising_edge(clk) then\n    if sysCycle = sysCycleDef\'high then sysCycle <= sysCycleDef\'low; else sysCycle <= sysCycleDef\'succ(sysCycle); end if;\n  end if; end process;\n{PIXEL}{PHI2}{SHAPER}  -- checker: print one full PHI2 cycle after warm-up and verify the claims\n  process\n    variable hi, n : integer := 0;\n    variable prev_cart_dotclk_q, prev_phi : std_logic := \'0\';\n    variable dist_rise, dist_fall : integer := -1;\n    variable last_cart_dotclk_q_edge : integer := -100;\n    variable t : integer := 0;\n  begin\n    wait for 64 * 31.72 ns;      -- warm-up: delay line and counters settled\n    wait until rising_edge(clk);\n    wait until sysCycle = CYCLE_EXT0;\n    prev_cart_dotclk_q := cart_dotclk_q; prev_phi := phi2;\n    for i in 0 to 63 loop\n      wait until rising_edge(clk); wait for 1 ns;\n      t := i;\n      if cart_dotclk_q /= prev_cart_dotclk_q then last_cart_dotclk_q_edge := t; end if;\n      if phi2 = \'1\' and prev_phi = \'0\' then dist_rise := t - last_cart_dotclk_q_edge; end if;\n      if phi2 = \'0\' and prev_phi = \'1\' then dist_fall := t - last_cart_dotclk_q_edge; end if;\n      if i < 32 then\n        report "tick " & integer\'image(i) & " " & sysCycleDef\'image(sysCycle) &\n               "  core_dotclk=" & std_logic\'image(enablePixel) & "  cart_dotclk_q=" & std_logic\'image(cart_dotclk_q) &\n               "  phi2=" & std_logic\'image(phi2);\n        if cart_dotclk_q = \'1\' then hi := hi + 1; end if;\n        n := n + 1;\n      end if;\n      prev_cart_dotclk_q := cart_dotclk_q; prev_phi := phi2;\n    end loop;\n    report "cart_dotclk_q high ticks per 32-tick cycle: " & integer\'image(hi) & " (expect 16)";\n    report "ticks from the last cart_dotclk_q edge to the PHI2 rising edge: " & integer\'image(dist_rise) & " (expect 1)";\n    report "ticks from the last cart_dotclk_q edge to the PHI2 falling edge: " & integer\'image(dist_fall) & " (expect 1)";\n    assert hi = 16 report "DUTY CYCLE WRONG" severity failure;\n    assert dist_rise = 1 and dist_fall = 1 report "PHI2 EDGE CLEARANCE WRONG" severity failure;\n    report "ALL CHECKS PASSED";\n    done <= true; wait;\n  end process;\nend;\n'
TB_DMA_BA = 'library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;\nentity tb_dma_ba is end;\narchitecture sim of tb_dma_ba is\n{ENUM}\n  constant C_SIM_CRT : natural := 0;\n  constant C_CART_BA_RECHARGE_TICKS : natural := 4;\n  constant C_CART_DMA_GRACE_RD_CYCLES : natural := 3;\n  signal clk_main_i : std_logic := \'0\';\n  signal sysCycle : sysCycleDef := CYCLE_EXT0;\n  signal c64_exp_port_mode_i : std_logic_vector(3 downto 0) := "0000";\n  signal cart_in_dma_n_q, cart_in_rw_q : std_logic := \'1\';\n  signal cpuWe, ba_dma : std_logic := \'0\';\n  signal dma_grace : std_logic;\n  signal rec_rw : std_logic := \'1\';\n  signal cart_in_a_q : unsigned(15 downto 0) := x"5000";\n  signal baLoc : std_logic := \'1\';\n  signal dma_active : std_logic := \'0\';\n  signal cpuHasBus : std_logic := \'0\';\n  signal core_dma_cycle, core_ba, core_phi2 : std_logic;\n  signal phi2 : std_logic := \'0\';\n  -- unit under test registers (verbatim from main.vhd)\n  signal core_ba_q : std_logic := \'1\';\n  signal core_dma_cycle_q : std_logic := \'0\';\n  signal core_dma_last_we : std_logic := \'0\';\n  signal core_dma_last_addr_p1 : unsigned(15 downto 0) := (others => \'0\');\n  signal core_dma_last_valid, core_dma_prev_we, core_dma_prev_valid, core_dma_grace_rd : std_logic := \'0\';\n  signal core_dma_grace_armed, core_dma_grace : std_logic := \'0\';\n  signal core_dma_grace_cnt : natural range 0 to C_CART_DMA_GRACE_RD_CYCLES - 1 := 0;\n  signal cart_ba_recharge, cart_ba_drive_high : std_logic := \'0\';\n  signal cart_ba_recharge_cnt : natural range 0 to C_CART_BA_RECHARGE_TICKS - 1 := 0;\n  signal cart_phi_low_cnt : natural range 0 to 31 := 0;\n  signal cart_phi2_q : std_logic := \'0\';\n  signal cart_ctrl_oe_o, cart_ba_o, cart_io1_o, cart_io2_o, cart_rw_o, cart_data_oe_o, core_dma_we : std_logic;\n  signal done : boolean := false;\n  function img(s : std_logic) return string is begin return std_logic\'image(s)(2 to 2); end;\nbegin\n  clk_main_i <= not clk_main_i after 15.86 ns when not done;\n  core_ba <= baLoc; core_phi2 <= phi2; dma_grace <= core_dma_grace;\n  process(clk_main_i) begin if rising_edge(clk_main_i) then\n    if sysCycle = sysCycleDef\'high then sysCycle <= sysCycleDef\'low; else sysCycle <= sysCycleDef\'succ(sysCycle); end if;\n    case sysCycle is when CYCLE_CPU0 => phi2 <= \'1\'; when CYCLE_CPUE => phi2 <= \'0\'; when others => null; end case;\n    if sysCycle = sysCycleDef\'pred(CYCLE_CPU0) then\n      cpuHasBus <= \'0\';\n      {GRANT} cpuHasBus <= \'1\'; end if;\n    end if;\n    if sysCycle = sysCycleDef\'high then cpuHasBus <= \'0\'; end if;\n    if cart_ctrl_oe_o = \'1\' then cart_in_rw_q <= cart_rw_o; else cart_in_rw_q <= rec_rw; end if;\n  end if; end process;\n  core_dma_cycle <= \'1\' when (sysCycle >= CYCLE_CPU0 and sysCycle <= CYCLE_CPUF) and cpuHasBus = \'1\' and dma_active = \'1\' else \'0\';\n\n{BAPROC}\n\n  dma_branch : process (all) begin\n    cart_ctrl_oe_o <= \'0\'; cart_ba_o <= core_ba; cart_io1_o <= \'0\'; cart_io2_o <= \'0\'; cart_rw_o <= \'0\';\n    cart_data_oe_o <= cart_in_rw_q; core_dma_we <= not cart_in_rw_q;\n    if cart_in_dma_n_q = \'0\' then\n{DMABRANCH}\n    end if;\n  end process;\n\n  stim : process\n    procedure tick(n : natural := 1) is begin for i in 1 to n loop wait until rising_edge(clk_main_i); wait for 1 ns; end loop; end;\n    procedure show(tag : string) is begin\n      report tag & " " & sysCycleDef\'image(sysCycle) & " ba=" & img(core_ba) & " cyc=" & img(core_dma_cycle) &\n        " grace=" & img(core_dma_grace) & " gcnt=" & integer\'image(core_dma_grace_cnt) & " rd=" & img(core_dma_grace_rd) & " armed=" & img(core_dma_grace_armed) & " lastwe=" & img(core_dma_last_we) & " prevwe=" & img(core_dma_prev_we) & " rech=" & img(cart_ba_recharge) &\n        " drvhi=" & img(cart_ba_drive_high) & " cnt=" & integer\'image(cart_ba_recharge_cnt) & " baq=" & img(core_ba_q) & " plc=" & integer\'image(cart_phi_low_cnt) & " | oe=" & img(cart_ctrl_oe_o) & " BA=" & img(cart_ba_o) &\n        " RW=" & img(cart_rw_o) & " doe=" & img(cart_data_oe_o) & " we=" & img(core_dma_we);\n    end;\n    procedure goto_cycle(c : sysCycleDef) is begin wait until sysCycle = c; wait for 1 ns; end;\n    variable errs : natural := 0;\n    procedure chk(cond : boolean; msg : string) is begin if not cond then errs := errs + 1; report "FAIL: " & msg severity error; end if; end;\n  begin\n    wait for 100 ns;\n    -- ===== S1: fetch (cartridge writes), badline BA fall at EXT1, 40-cycle stall, badline rise at EXT1 =====\n    cart_in_dma_n_q <= \'0\'; dma_active <= \'1\'; rec_rw <= \'0\'; cart_in_a_q <= x"5010"; tick(2);\n    goto_cycle(CYCLE_CPUF); chk(core_dma_cycle = \'1\', "S1 served write cycle before the stall");\n    goto_cycle(CYCLE_EXT0); baLoc <= \'0\'; cart_in_a_q <= x"5011";\n    goto_cycle(CYCLE_EXT2); show("S1 EXT2");\n    chk(core_dma_grace = \'1\' and core_dma_grace_armed = \'0\', "S1 grace set and disarmed by EXT2");\n    goto_cycle(CYCLE_CPU0); show("S1 CPU0");\n    chk(cpuHasBus = \'1\' and core_dma_cycle = \'1\', "S1 grace cycle granted");\n    chk(cart_ctrl_oe_o = \'1\' and cart_ba_o = \'0\' and cart_rw_o = \'0\' and cart_data_oe_o = \'0\' and core_dma_we = \'1\', "S1 grace cycle: BA=0 RW=0, write enabled");\n    goto_cycle(CYCLE_CPUF); chk(core_dma_we = \'1\', "S1 grace write enabled at CPUF (final sample)");\n    goto_cycle(CYCLE_EXT1); show("S1 EXT1 next");\n    chk(core_dma_grace = \'0\' and core_dma_last_we = \'1\' and core_dma_grace_armed = \'0\', "S1 grace cleared, last_we kept, not re-armed");\n    goto_cycle(CYCLE_CPU0); chk(core_dma_cycle = \'0\' and cart_rw_o = \'1\' and core_dma_we = \'0\', "S1 stall: RW=1, no write");\n    for i in 1 to 40 loop goto_cycle(CYCLE_EXT0); end loop;\n    baLoc <= \'1\';                                  -- badline rise at EXT1 (register), VIC half\n    goto_cycle(CYCLE_EXT1); show("S1 rise EXT1 (tick 1)");\n    chk(cart_ba_drive_high = \'1\' and cart_ctrl_oe_o = \'1\' and cart_ba_o = \'1\' and cart_rw_o = \'1\' and core_dma_we = \'0\', "S1 immediate recharge from tick 1: BA driven high, RW fail-safe high, no RAM write");\n    goto_cycle(CYCLE_DMA0); show("S1 rise DMA0 (tick 4)");\n    chk(cart_ba_drive_high = \'1\' and cart_ba_recharge = \'1\' and cart_ba_o = \'1\', "S1 fourth drive tick (DMA0) still driving");\n    goto_cycle(CYCLE_DMA1); show("S1 rise DMA1 (tick 5)");\n    chk(cart_ba_recharge = \'0\' and cart_ba_drive_high = \'1\' and cart_ctrl_oe_o = \'0\' and cart_ba_o = \'1\', "S1 tick 5: recharge off, drive_high still set, transceiver input, BA mux = 1 (glitch-free)");\n    goto_cycle(CYCLE_DMA2); chk(cart_ba_drive_high = \'0\', "S1 tick 6: drive_high cleared one tick after recharge");\n    goto_cycle(CYCLE_CPU0); show("S1 resume CPU0");\n    chk(core_dma_cycle = \'1\' and cart_ctrl_oe_o = \'0\' and core_dma_we = \'1\', "S1 resume cycle served, cartridge write accepted from CPU0");\n    goto_cycle(CYCLE_CPUF); chk(core_dma_grace_armed = \'1\', "S1 served write re-arms the grace");\n    -- ===== S2: stash/verify (reads), badline fall -> grace read (the REC repeats this read); rise -> immediate recharge with RW=1 =====\n    rec_rw <= \'1\'; goto_cycle(CYCLE_CPUF); goto_cycle(CYCLE_CPUF);\n    goto_cycle(CYCLE_EXT0); baLoc <= \'0\';\n    goto_cycle(CYCLE_CPU3); show("S2 stall CPU3");\n    chk(core_dma_grace = \'1\' and core_dma_grace_rd = \'1\' and core_dma_cycle = \'1\' and cart_ctrl_oe_o = \'1\' and cart_ba_o = \'0\' and cart_rw_o = \'1\' and cart_data_oe_o = \'1\' and core_dma_we = \'0\', "S2 read, read, then stall: grace read, BA low, RW high, read data driven, no RAM write");\n    goto_cycle(CYCLE_EXT1); chk(core_dma_grace = \'1\' and core_dma_grace_cnt = 1 and core_dma_grace_armed = \'0\', "S2 grace continues after the first served grace read (count 1), not re-armed");\n    goto_cycle(CYCLE_CPU3); show("S2 second stall cycle CPU3");\n    chk(core_dma_grace = \'1\' and core_dma_grace_rd = \'1\' and core_dma_cycle = \'1\' and cart_ctrl_oe_o = \'1\' and cart_ba_o = \'0\' and cart_rw_o = \'1\' and cart_data_oe_o = \'1\' and core_dma_we = \'0\', "S2 second BA-low cycle: grace read served, data driven, BA low, RW high, no RAM write");\n    goto_cycle(CYCLE_EXT1); chk(core_dma_grace = \'1\' and core_dma_grace_cnt = 2, "S2 grace continues after the second served grace read (count 2)");\n    goto_cycle(CYCLE_CPU3); show("S2 third stall cycle CPU3");\n    chk(core_dma_grace = \'1\' and core_dma_cycle = \'1\' and cart_ba_o = \'0\' and cart_rw_o = \'1\' and cart_data_oe_o = \'1\' and core_dma_we = \'0\', "S2 third BA-low cycle: grace read served, data driven");\n    goto_cycle(CYCLE_EXT1); chk(core_dma_grace = \'0\' and core_dma_grace_armed = \'0\' and core_dma_last_we = \'0\', "S2 grace ends after C_CART_DMA_GRACE_RD_CYCLES served reads, not re-armed, history = read");\n    goto_cycle(CYCLE_CPU3); show("S2 fourth stall cycle CPU3");\n    chk(core_dma_grace = \'0\' and core_dma_cycle = \'0\' and cart_data_oe_o = \'0\' and cart_rw_o = \'1\' and core_dma_we = \'0\', "S2 fourth BA-low cycle (VIC owns the bus): data floating, RW high, no write");\n    for i in 1 to 2 loop goto_cycle(CYCLE_EXT0); end loop; baLoc <= \'1\';\n    goto_cycle(CYCLE_EXT2); show("S2 rise EXT2");\n    chk(cart_ba_drive_high = \'1\' and cart_ba_o = \'1\' and cart_rw_o = \'1\' and core_dma_we = \'0\', "S2 recharge with RW=1 (last was read)");\n    goto_cycle(CYCLE_CPU2); chk(cart_ctrl_oe_o = \'0\' and cart_data_oe_o = \'1\' and core_dma_we = \'0\', "S2 served read cycle: FPGA drives read data");\n    -- ===== S3: fetch, sprite BA fall at the VIC3->CPU0 edge (cycle already granted) =====\n    rec_rw <= \'0\'; cart_in_a_q <= x"6000"; goto_cycle(CYCLE_CPUF); goto_cycle(CYCLE_CPUF);\n    goto_cycle(CYCLE_CPU0); baLoc <= \'0\'; cart_in_a_q <= x"6001"; wait for 1 ns; show("S3 CPU0");\n    chk(core_dma_cycle = \'1\', "S3 BA fall at the grant edge ($D011 corner case): cycle already granted");\n    goto_cycle(CYCLE_CPU1); show("S3 CPU1");\n    chk(core_dma_grace = \'1\' and cart_rw_o = \'0\' and core_dma_we = \'1\', "S3 grace active from CPU1, write served");\n    goto_cycle(CYCLE_CPUF); chk(core_dma_we = \'1\', "S3 write enabled at CPUF");\n    goto_cycle(CYCLE_EXT1); chk(core_dma_grace = \'0\', "S3 grace cleared");\n    -- sprite stall of 3 cycles, rise at the VIC3->CPU0 edge: hold low, recharge in the next served cycle\n    for i in 1 to 2 loop goto_cycle(CYCLE_EXT0); end loop;\n    goto_cycle(CYCLE_CPU0); baLoc <= \'1\'; wait for 1 ns; show("S3 sprite rise CPU0");\n    chk(core_dma_cycle = \'0\' and cart_ctrl_oe_o = \'1\' and cart_ba_o = \'0\', "S3 sprite rise: unserved cycle, BA held low");\n    goto_cycle(CYCLE_CPUF); chk(cart_ba_o = \'0\' and cart_ba_drive_high = \'0\', "S3 still held low at CPUF of the unserved cycle");\n    goto_cycle(CYCLE_CPU0); show("S3 next CPU0"); chk(core_dma_cycle = \'1\' and cart_ba_o = \'0\', "S3 served cycle CPU0: still low (drive starts next tick)");\n    goto_cycle(CYCLE_CPU1); chk(cart_ba_drive_high = \'1\' and cart_ba_o = \'1\' and cart_rw_o = \'1\', "S3 CPU1: BA driven high, RW fail-safe high");\n    goto_cycle(CYCLE_CPU6); show("S3 CPU6"); chk(cart_ctrl_oe_o = \'0\' and core_dma_we = \'1\', "S3 CPU6: input mode, write served");\n    -- ===== S4: second BA fall without a served write in between -> no grace =====\n    goto_cycle(CYCLE_CPUF); goto_cycle(CYCLE_EXT0); baLoc <= \'0\'; cart_in_a_q <= x"6002";       -- fall 1: grace (armed by the served write)\n    goto_cycle(CYCLE_CPU3); chk(core_dma_grace = \'1\' and core_dma_we = \'1\', "S4 first fall: grace write");\n    goto_cycle(CYCLE_EXT0); goto_cycle(CYCLE_EXT0); baLoc <= \'1\';                                -- rise (VIC half)\n    goto_cycle(CYCLE_EXT7); baLoc <= \'0\';                                                        -- fall again before any served cycle\n    goto_cycle(CYCLE_CPU3); show("S4 second fall CPU3");\n    chk(core_dma_grace = \'0\' and core_dma_we = \'0\', "S4 second fall without a served write: no grace, no write");\n    -- ===== S4b: idle cartridge leaves the previous address on the bus -> grace granted, no write =====\n    for i in 1 to 3 loop goto_cycle(CYCLE_EXT0); end loop; baLoc <= \'1\';\n    goto_cycle(CYCLE_CPU6); cart_in_a_q <= x"6010"; goto_cycle(CYCLE_CPUF); goto_cycle(CYCLE_CPUF);  -- served writes at 6010\n    goto_cycle(CYCLE_EXT0); baLoc <= \'0\';                                                          -- bus keeps 6010 (bus-hold)\n    goto_cycle(CYCLE_CPU3); show("S4b CPU3");\n    chk(core_dma_grace = \'1\' and core_dma_grace_rd = \'0\' and core_dma_we = \'0\' and cart_rw_o = \'0\', "S4b same address as the last write: no RAM write");\n    -- ===== S7: swap (read then write of the same byte), BA falls after the write half: the REC holds the read of the first BA-low cycle through the AEC window =====\n    for i in 1 to 3 loop goto_cycle(CYCLE_EXT0); end loop; baLoc <= \'1\';\n    goto_cycle(CYCLE_CPU6); rec_rw <= \'1\'; cart_in_a_q <= x"7000"; goto_cycle(CYCLE_CPUF);         -- read  C64[7000]\n    goto_cycle(CYCLE_CPU0); rec_rw <= \'0\';                     goto_cycle(CYCLE_CPUF);              -- write C64[7000]\n    goto_cycle(CYCLE_EXT0); baLoc <= \'0\'; rec_rw <= \'1\'; cart_in_a_q <= x"7001";                    -- REC reads C64[7001] in the first BA-low cycle\n    goto_cycle(CYCLE_CPU3); show("S7 CPU3");\n    chk(core_dma_grace = \'1\' and core_dma_grace_rd = \'1\' and core_dma_cycle = \'1\' and cart_ctrl_oe_o = \'1\' and cart_ba_o = \'0\' and cart_rw_o = \'1\' and cart_data_oe_o = \'1\' and core_dma_we = \'0\', "S7 swap: grace served as a read, BA low, RW high, data driven, no RAM write");\n    goto_cycle(CYCLE_EXT1); chk(core_dma_grace = \'1\' and core_dma_grace_cnt = 1 and core_dma_last_we = \'1\' and core_dma_grace_armed = \'0\', "S7 swap: grace continues after the first served read (count 1), history untouched, not re-armed");\n    goto_cycle(CYCLE_CPU3); show("S7 second stall cycle CPU3");\n    chk(core_dma_grace = \'1\' and core_dma_grace_rd = \'1\' and core_dma_cycle = \'1\' and cart_ctrl_oe_o = \'1\' and cart_ba_o = \'0\' and cart_rw_o = \'1\' and cart_data_oe_o = \'1\' and core_dma_we = \'0\', "S7 second BA-low cycle after a swap write: held read served, data driven, no RAM write");\n    goto_cycle(CYCLE_EXT1); chk(core_dma_grace = \'1\' and core_dma_grace_cnt = 2, "S7 swap: grace continues after the second served read (count 2)");\n    goto_cycle(CYCLE_CPU3); show("S7 third stall cycle CPU3");\n    chk(core_dma_grace = \'1\' and core_dma_cycle = \'1\' and cart_ba_o = \'0\' and cart_rw_o = \'1\' and cart_data_oe_o = \'1\' and core_dma_we = \'0\', "S7 third BA-low cycle after a swap write: held read served, data driven");\n    goto_cycle(CYCLE_EXT1); chk(core_dma_grace = \'0\' and core_dma_last_we = \'0\' and core_dma_prev_we = \'1\' and core_dma_grace_armed = \'0\', "S7 swap: grace ends after C_CART_DMA_GRACE_RD_CYCLES served reads, history = read after write, not re-armed");\n    goto_cycle(CYCLE_CPU3); show("S7 fourth stall cycle CPU3");\n    chk(core_dma_grace = \'0\' and core_dma_cycle = \'0\' and cart_data_oe_o = \'0\' and cart_rw_o = \'1\' and core_dma_we = \'0\', "S7 fourth BA-low cycle (VIC owns the bus): not served, data floating, RW high");\n    for i in 1 to 2 loop goto_cycle(CYCLE_EXT0); end loop; baLoc <= \'1\';\n    goto_cycle(CYCLE_CPU6); rec_rw <= \'0\'; goto_cycle(CYCLE_CPUF);                                 -- write C64[7001] after the stall\n    chk(core_dma_cycle = \'1\' and core_dma_we = \'1\', "S7 swap: the write after the stall is served");\n    goto_cycle(CYCLE_EXT0); baLoc <= \'0\'; rec_rw <= \'1\'; cart_in_a_q <= x"7002";\n    goto_cycle(CYCLE_CPU3); show("S7b CPU3");\n    chk(core_dma_grace = \'1\' and core_dma_grace_rd = \'1\' and cart_data_oe_o = \'1\', "S7b swap continues: next stall is again a grace read");\n    -- ===== S7c: swap, BA falls after the read half (the write of the same byte would follow) -> no grace, data floating =====\n    for i in 1 to 3 loop goto_cycle(CYCLE_EXT0); end loop; baLoc <= \'1\';\n    goto_cycle(CYCLE_CPU6); rec_rw <= \'0\'; goto_cycle(CYCLE_CPUF);                                 -- write C64[7002] after the stall\n    goto_cycle(CYCLE_CPU0); rec_rw <= \'1\'; cart_in_a_q <= x"7003"; goto_cycle(CYCLE_CPUF);         -- read  C64[7003]\n    goto_cycle(CYCLE_EXT0); baLoc <= \'0\';\n    goto_cycle(CYCLE_CPU3); show("S7c CPU3");\n    chk(core_dma_grace = \'0\' and core_dma_cycle = \'0\' and cart_data_oe_o = \'0\' and cart_rw_o = \'1\' and core_dma_we = \'0\', "S7c swap read after a write, then stall: no grace, data floating, RW high");\n    -- ===== S5: implausible address in a grace cycle -> no write =====\n    for i in 1 to 3 loop goto_cycle(CYCLE_EXT0); end loop; baLoc <= \'1\';\n    goto_cycle(CYCLE_CPU6); rec_rw <= \'0\'; cart_in_a_q <= x"6003"; goto_cycle(CYCLE_CPUF); goto_cycle(CYCLE_CPUF); goto_cycle(CYCLE_CPUF);\n    goto_cycle(CYCLE_EXT0); baLoc <= \'0\'; cart_in_a_q <= x"F00D";\n    goto_cycle(CYCLE_CPU3); show("S5 CPU3");\n    chk(core_dma_grace = \'1\' and core_dma_we = \'0\', "S5 grace granted but implausible address: no write");\n    -- ===== S6: /DMA released during a stall clears everything =====\n    cart_in_dma_n_q <= \'1\'; dma_active <= \'0\'; tick(2); show("S6");\n    chk(core_dma_grace = \'0\' and core_dma_grace_rd = \'0\' and core_dma_grace_armed = \'0\' and cart_ba_recharge = \'0\' and cart_ba_drive_high = \'0\' and core_dma_last_we = \'0\' and core_dma_last_valid = \'0\' and core_dma_prev_valid = \'0\' and core_dma_grace_cnt = 0, "S6 all state cleared when /DMA goes high");\n    baLoc <= \'1\';\n    -- ===== S8: the very first served cycle of a session is a read, then BA falls -> grace read =====\n    goto_cycle(CYCLE_EXT0); cart_in_dma_n_q <= \'0\'; dma_active <= \'1\'; rec_rw <= \'1\'; cart_in_a_q <= x"8000"; tick(2);\n    goto_cycle(CYCLE_CPUF); chk(core_dma_cycle = \'1\' and core_dma_prev_valid = \'0\', "S8 first served read, no history");\n    goto_cycle(CYCLE_EXT0); baLoc <= \'0\';\n    goto_cycle(CYCLE_CPU3); show("S8 CPU3");\n    chk(core_dma_grace = \'1\' and core_dma_grace_rd = \'1\' and cart_data_oe_o = \'1\' and cart_rw_o = \'1\' and core_dma_we = \'0\', "S8 first read then stall: grace read, data driven");\n    goto_cycle(CYCLE_CPU3); chk(core_dma_grace = \'1\' and core_dma_cycle = \'1\' and cart_data_oe_o = \'1\', "S8 second BA-low cycle served as a read");\n    goto_cycle(CYCLE_CPU3); chk(core_dma_grace = \'1\' and core_dma_cycle = \'1\' and cart_data_oe_o = \'1\', "S8 third BA-low cycle served as a read");\n    goto_cycle(CYCLE_CPU3); show("S8 fourth CPU3"); chk(core_dma_grace = \'0\' and core_dma_cycle = \'0\' and cart_data_oe_o = \'0\', "S8 fourth BA-low cycle: not served, data floating");\n    for i in 1 to 3 loop goto_cycle(CYCLE_EXT0); end loop; baLoc <= \'1\'; cart_in_dma_n_q <= \'1\'; dma_active <= \'0\'; tick(2);\n    -- ===== S9: BA rises after two BA-low cycles while a read grace is running (a VIC stall never does this; a DMA write to $D011 could) =====\n    goto_cycle(CYCLE_EXT0); cart_in_dma_n_q <= \'0\'; dma_active <= \'1\'; rec_rw <= \'1\'; cart_in_a_q <= x"9000"; tick(2);\n    goto_cycle(CYCLE_CPUF); goto_cycle(CYCLE_CPUF); chk(core_dma_cycle = \'1\', "S9 served reads");\n    goto_cycle(CYCLE_EXT0); baLoc <= \'0\';\n    goto_cycle(CYCLE_CPU3); chk(core_dma_grace = \'1\' and core_dma_grace_rd = \'1\' and cart_data_oe_o = \'1\', "S9 first BA-low cycle: grace read");\n    goto_cycle(CYCLE_CPU3); chk(core_dma_grace = \'1\' and core_dma_grace_cnt = 1 and cart_data_oe_o = \'1\', "S9 second BA-low cycle: grace read");\n    goto_cycle(CYCLE_EXT0); baLoc <= \'1\';\n    goto_cycle(CYCLE_EXT2); show("S9 rise EXT2");\n    chk(core_dma_grace = \'0\' and core_dma_last_we = \'0\' and cart_ba_drive_high = \'1\' and cart_ba_o = \'1\' and cart_rw_o = \'1\' and core_dma_we = \'0\', "S9 BA rose: grace ended early, history = read, recharge with RW=1");\n    goto_cycle(CYCLE_CPU2); chk(core_dma_cycle = \'1\' and core_dma_grace = \'0\' and cart_ctrl_oe_o = \'0\' and cart_data_oe_o = \'1\' and core_dma_we = \'0\', "S9 resume cycle served normally as a read");\n    goto_cycle(CYCLE_CPUF); chk(core_dma_grace_armed = \'1\' and core_dma_grace_cnt = 0, "S9 served read re-arms the grace");\n    goto_cycle(CYCLE_EXT0); cart_in_dma_n_q <= \'1\'; dma_active <= \'0\'; tick(2);\n    if errs = 0 then report "ALL CHECKS PASSED"; else report integer\'image(errs) & " CHECKS FAILED" severity error; end if;\n    done <= true; wait;\n  end process;\nend;\n'
open(out + "/tb_dotclk.vhd", "w").write(TB_DOTCLK.replace("{ENUM}", "  " + enum).replace("{PIXEL}", pixel + "\n").replace("{PHI2}", phi2p + "\n").replace("{SHAPER}", shaper + "\n"))
